description:
Implement a `createStore` factory that returns a `useStore` hook. The store holds state, supports a `setState` updater, and notifies all subscribers on change — similar to Zustand.

**Example:**
```tsx
const useCount = createStore({ count: 0 });
const { count, setState } = useCount();
setState(s => ({ ...s, count: s.count + 1 }));
```

starter_code:
import { useSyncExternalStore, useCallback } from 'react';

export function createStore<T>(initialState: T) {
  // your code here
  // return a useStore hook
}

test_suite:
test('returns initial state', () => {
  const useCount = createStore({ count: 0 });
  const { result } = renderHook(() => useCount());
  expect(result.current.count).toBe(0);
});

test('setState updates state', () => {
  const useCount = createStore({ count: 0 });
  const { result } = renderHook(() => useCount());
  act(() => result.current.setState(s => ({ count: s.count + 1 })));
  expect(result.current.count).toBe(1);
});

test('two hooks share same state', () => {
  const useCount = createStore({ count: 0 });
  const { result: a } = renderHook(() => useCount());
  const { result: b } = renderHook(() => useCount());
  act(() => a.current.setState(() => ({ count: 42 })));
  expect(b.current.count).toBe(42);
});

// __hidden__
test('each createStore creates independent state', () => {
  const useA = createStore({ n: 0 });
  const useB = createStore({ n: 0 });
  const { result: a } = renderHook(() => useA());
  const { result: b } = renderHook(() => useB());
  act(() => a.current.setState(() => ({ n: 9 })));
  expect(b.current.n).toBe(0);
});

solution:
import { useSyncExternalStore, useCallback } from 'react';

export function createStore<T>(initialState: T) {
  let state = initialState;
  const listeners = new Set<() => void>();
  const subscribe = (listener: () => void) => {
    listeners.add(listener);
    return () => listeners.delete(listener);
  };
  const getSnapshot = () => state;
  return function useStore() {
    const currentState = useSyncExternalStore(subscribe, getSnapshot);
    const setState = useCallback((updater: (s: T) => T) => {
      state = updater(state);
      listeners.forEach(l => l());
    }, []);
    return { ...currentState, setState } as T & { setState: (updater: (s:T)=>T) => void };
  };
}
